                let (off, n) = d.len_body();
                let mut es = Dec::new(&buf0[off..off + n]);
                a_results[n_results].write(dec_result_raw_fix(&mut es, base0 + off, u.at(1)));
                if es.err != 0 { d.err = es.err; }
                n_results += 1;
